const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    if (this.window) this.window = undefined;
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;
    this._boot();
  }

  // Reload on the SAME window. happy-dom keeps localStorage and location.hash per Window
  // instance (a fresh Window starts empty), so a real reload that preserves the user's
  // persisted todos and active filter must reuse the live window rather than build a new
  // one. The document is re-written and the app re-evaluated, but the window's persisted
  // state survives the reload.
  reloadApp() {
    if (!this.window) throw new Error('verification support: reloadApp() before the app was loaded');
    this.document = this.window.document;
    this._boot();
  }

  _boot() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    if (!w.__ssRouterAdded) {
      this.document.addEventListener('click', (e) => {
        const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
        if (!a) return;
        const next = a.getAttribute('href');
        if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
      }, true);
      w.__ssRouterAdded = true;
    }
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

const { Given, When, Then } = require('@cucumber/cucumber');

// ---- helpers ----------------------------------------------------------------

function findTodoLi(doc, title) {
  const lis = doc.querySelectorAll('.todo-list li');
  for (const li of lis) {
    const label = li.querySelector('label');
    if (label && label.textContent.trim() === title) return li;
  }
  return null;
}

// A todo keeps its data-id across renames, so resolve a scenario name first by its
// current title and, when that name no longer matches (the todo was edited), by the
// data-id recorded when the todo was created.
function findTodoLiByIdentity(world, name) {
  const byTitle = findTodoLi(world.document, name);
  if (byTitle) return byTitle;
  const ids = world.__todoId || {};
  const id = ids[name];
  if (id) return world.document.querySelector(`.todo-list li[data-id="${id}"]`);
  return null;
}

function editingLi(doc) {
  return doc.querySelector('.todo-list li.editing');
}

function addTodo(world, title) {
  const input = world.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new world.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  const li = findTodoLi(world.document, title);
  if (li) {
    world.__todoId = world.__todoId || {};
    world.__todoId[title] = li.dataset.id;
  }
}

function completeTodo(world, title) {
  const li = findTodoLiByIdentity(world, title);
  if (!li) throw new Error(`step: no todo with title "${title}" to complete`);
  const toggle = li.querySelector('.toggle');
  toggle.checked = !toggle.checked;
  toggle.dispatchEvent(new world.window.Event('change', { bubbles: true }));
}

function setEditAndDispatch(world, value, eventInit) {
  const li = editingLi(world.document);
  if (!li) throw new Error('step: no todo is in editing mode');
  const edit = li.querySelector('.edit');
  edit.value = value;
  const evt = eventInit.type === 'blur'
    ? new world.window.Event('blur')
    : new world.window.KeyboardEvent('keydown', { key: eventInit.key, bubbles: true });
  edit.dispatchEvent(evt);
}

// ---- Given: app load with seeded state --------------------------------------

Given('the app loads with no todos', function () {});

Given('the app loads with active todo {string}', function (title) {
  addTodo(this, title);
});

Given('the app loads with active todos {string} and {string}', function (a, b) {
  addTodo(this, a);
  addTodo(this, b);
});

Given('the app loads with active todos {string} and {string} and completed todo {string}', function (a, b, c) {
  addTodo(this, a);
  addTodo(this, b);
  addTodo(this, c);
  completeTodo(this, c);
});

Given('the app loads with active todo {string} and completed todo {string}', function (a, b) {
  addTodo(this, a);
  addTodo(this, b);
  completeTodo(this, b);
});

Given('the app loads with completed todo {string}', function (title) {
  addTodo(this, title);
  completeTodo(this, title);
});

Given('the app loads with completed todos {string} and {string}', function (a, b) {
  addTodo(this, a);
  addTodo(this, b);
  completeTodo(this, a);
  completeTodo(this, b);
});

Given('the app loads with todo {string}', function (title) {
  addTodo(this, title);
});

// ---- When: actions ----------------------------------------------------------

When('I type {string} into the new-todo input and press Enter', function (title) {
  addTodo(this, title);
});

When('I complete the todo {string}', function (title) {
  completeTodo(this, title);
});

When('I click the toggle-all control', function () {
  const ta = this.document.querySelector('#toggle-all');
  ta.checked = !ta.checked;
  ta.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I double-click the label of the todo {string}', function (title) {
  const li = findTodoLiByIdentity(this, title);
  if (!li) throw new Error(`step: no todo with title "${title}"`);
  const label = li.querySelector('label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I set the edit input to {string} and press Enter', function (value) {
  setEditAndDispatch(this, value, { type: 'keydown', key: 'Enter' });
});

When('I set the edit input to {string} and blur', function (value) {
  setEditAndDispatch(this, value, { type: 'blur' });
});

When('I set the edit input to {string} and press Escape', function (value) {
  setEditAndDispatch(this, value, { type: 'keydown', key: 'Escape' });
});

When('I click the clear-completed button', function () {
  this.document.querySelector('.clear-completed').click();
});

When('I open the {string} filter', function (name) {
  const href = name === 'All' ? '#/' : `#/${name.toLowerCase()}`;
  const link = this.document.querySelector(`.filters a[href="${href}"]`);
  if (!link) throw new Error(`step: no filter link for "${name}"`);
  link.click();
});

When('I reload the app', function () {
  this.reloadApp();
});

// ---- Then: assertions -------------------------------------------------------

Then('the main section is hidden', function () {
  const main = this.document.querySelector('#main');
  if (!main.hidden) throw new Error('main section is not hidden');
});

Then('the footer is hidden', function () {
  const footer = this.document.querySelector('#footer');
  if (!footer.hidden) throw new Error('footer is not hidden');
});

Then('the new-todo input is focused', function () {
  const input = this.document.querySelector('.new-todo');
  if (this.document.activeElement !== input) throw new Error('new-todo input is not focused');
});

Then('the todo list shows one item with title {string}', function (title) {
  const lis = this.document.querySelectorAll('.todo-list li');
  if (lis.length !== 1) throw new Error(`expected 1 todo item, found ${lis.length}`);
  if (!findTodoLi(this.document, title)) throw new Error(`no todo item with title "${title}"`);
});

Then('the new-todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  if (input.value !== '') throw new Error('new-todo input is not empty');
});

Then('the todo list shows no items', function () {
  const lis = this.document.querySelectorAll('.todo-list li');
  if (lis.length !== 0) throw new Error(`expected 0 todo items, found ${lis.length}`);
});

Then('the counter shows {string}', function (expected) {
  const count = this.document.querySelector('.todo-count');
  const actual = count.textContent.replace(/\s+/g, ' ').trim();
  if (actual !== expected) throw new Error(`counter shows "${actual}", expected "${expected}"`);
});

Then('the todo {string} shows the completed state', function (title) {
  const li = findTodoLi(this.document, title);
  if (!li) throw new Error(`no todo with title "${title}"`);
  if (!li.classList.contains('completed')) throw new Error(`todo "${title}" is not completed`);
});

Then('every todo item shows the completed state', function () {
  const lis = this.document.querySelectorAll('.todo-list li');
  if (lis.length === 0) throw new Error('no todo items to check');
  for (const li of lis) {
    if (!li.classList.contains('completed')) throw new Error('a todo item is not completed');
  }
});

Then('every todo item shows the active state', function () {
  const lis = this.document.querySelectorAll('.todo-list li');
  if (lis.length === 0) throw new Error('no todo items to check');
  for (const li of lis) {
    if (li.classList.contains('completed')) throw new Error('a todo item is completed when all should be active');
  }
});

Then('the toggle-all control is checked', function () {
  const ta = this.document.querySelector('#toggle-all');
  if (!ta.checked) throw new Error('toggle-all control is not checked');
});

Then('the toggle-all control is unchecked', function () {
  const ta = this.document.querySelector('#toggle-all');
  if (ta.checked) throw new Error('toggle-all control is checked');
});

Then('the todo {string} has a destroy control', function (title) {
  const li = findTodoLiByIdentity(this, title);
  if (!li) throw new Error(`no todo with title "${title}"`);
  if (!li.querySelector('.destroy')) throw new Error(`todo "${title}" has no destroy control`);
});

Then('the todo {string} is in editing mode', function (title) {
  const li = findTodoLiByIdentity(this, title);
  if (!li) throw new Error(`no todo with title "${title}"`);
  if (!li.classList.contains('editing')) throw new Error(`todo "${title}" is not in editing mode`);
});

Then('the todo {string} shows title {string}', function (title, expected) {
  const li = findTodoLiByIdentity(this, title);
  if (!li) throw new Error(`no todo with title "${title}"`);
  const actual = li.querySelector('label').textContent.trim();
  if (actual !== expected) throw new Error(`todo "${title}" shows title "${actual}", expected "${expected}"`);
});

Then('the todo {string} is not in editing mode', function (title) {
  const li = findTodoLiByIdentity(this, title);
  if (!li) throw new Error(`no todo with title "${title}"`);
  if (li.classList.contains('editing')) throw new Error(`todo "${title}" is still in editing mode`);
});

Then('the todo list shows two items', function () {
  const lis = this.document.querySelectorAll('.todo-list li');
  if (lis.length !== 2) throw new Error(`expected 2 todo items, found ${lis.length}`);
});

Then('the clear-completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn.hidden) throw new Error('clear-completed button is not hidden');
});

Then('the {string} filter link is selected', function (name) {
  const href = name === 'All' ? '#/' : `#/${name.toLowerCase()}`;
  const link = this.document.querySelector(`.filters a[href="${href}"]`);
  if (!link) throw new Error(`no filter link for "${name}"`);
  if (!link.classList.contains('selected')) throw new Error(`"${name}" filter link is not selected`);
});

// ---- Then: persistence assertions ------------------------------------------

function readStore(world, key) {
  const raw = world.localStorage.getItem(key);
  if (raw === null) throw new Error(`localStorage "${key}" is empty`);
  return JSON.parse(raw);
}

Then('localStorage {string} contains a todo with title {string}', function (key, title) {
  const todos = readStore(this, key);
  if (!todos.some((t) => t.title === title)) throw new Error(`localStorage "${key}" has no todo titled "${title}"`);
});

Then('localStorage {string} marks the todo {string} as completed', function (key, title) {
  const todos = readStore(this, key);
  const todo = todos.find((t) => t.title === title);
  if (!todo) throw new Error(`localStorage "${key}" has no todo titled "${title}"`);
  if (!todo.completed) throw new Error(`todo "${title}" is not marked completed in localStorage`);
});

Then(/^every stored todo under "([^"]*)" has the keys (.+)$/, function (key, keysParam) {
  const expected = keysParam
    .replace(/"/g, '')
    .split(/,|\band\b/)
    .map((s) => s.trim())
    .filter(Boolean);
  const todos = readStore(this, key);
  for (const t of todos) {
    for (const k of expected) {
      if (!Object.prototype.hasOwnProperty.call(t, k)) {
        throw new Error(`stored todo is missing key "${k}"`);
      }
    }
  }
});

Then('localStorage {string} records no editing state for the todo {string}', function (key, title) {
  const todos = readStore(this, key);
  const todo = todos.find((t) => t.title === title);
  if (!todo) throw new Error(`localStorage "${key}" has no todo titled "${title}"`);
  if (Object.prototype.hasOwnProperty.call(todo, 'editing')) {
    throw new Error(`localStorage "${key}" records an editing state for todo "${title}"`);
  }
});

(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanillajs';
  var ENTER_KEY = 'Enter';
  var ESCAPE_KEY = 'Escape';

  var todos = [];
  var route = 'all';
  var idCounter = 0;

  var newTodoInput, main, footer, todoList, toggleAll, clearCompleted, countEl;

  function uid() {
    idCounter += 1;
    return idCounter;
  }

  function escapeHtml(s) {
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  /** @planks("the app loads with no todos") */
  /** @planks("the new-todo input is focused") */
  function load() {
    var raw = window.localStorage.getItem(STORAGE_KEY);
    todos = raw ? JSON.parse(raw) : [];
    setRoute();
  }

  /** @planks("localStorage {string} contains a todo with title {string}")
   *  @planks("localStorage {string} marks the todo {string} as completed")
   */
  function save() {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function setRoute() {
    var hash = window.location.hash;
    if (hash === '#/active') route = 'active';
    else if (hash === '#/completed') route = 'completed';
    else route = 'all';
  }

  /** @planks("I open the {string} filter") */
  function isVisible(todo) {
    if (route === 'active') return !todo.completed;
    if (route === 'completed') return todo.completed;
    return true;
  }

  function todoTemplate(todo) {
    return (
      '<li class="' + (todo.completed ? 'completed' : '') + '" data-id="' + todo.id + '">' +
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">' +
      '</li>'
    );
  }

  /** @planks("the main section is hidden") */
  /** @planks("the footer is hidden") */
  /** @planks("the todo list shows no items") */
  /** @planks("the counter shows {string}") */
  /** @planks("the todo list shows two items") */
  /** @planks("the toggle-all control is unchecked") */
  /** @planks("the clear-completed button is hidden") */
  /** @planks("the {string} filter link is selected") */
  /** @planks("the todo {string} has a destroy control") */
  function render() {
    var visible = todos.filter(isVisible);
    todoList.innerHTML = visible.map(todoTemplate).join('');

    var hasTodos = todos.length > 0;
    main.hidden = !hasTodos;
    footer.hidden = !hasTodos;

    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    countEl.innerHTML = '<strong>' + activeCount + '</strong> ' + (activeCount === 1 ? 'item' : 'items') + ' left';

    toggleAll.checked = hasTodos && todos.every(function (t) { return t.completed; });
    clearCompleted.hidden = !todos.some(function (t) { return t.completed; });

    var links = footer.querySelectorAll('.filters a');
    for (var i = 0; i < links.length; i++) {
      var href = links[i].getAttribute('href');
      var r = href === '#/active' ? 'active' : href === '#/completed' ? 'completed' : 'all';
      if (r === route) links[i].classList.add('selected');
      else links[i].classList.remove('selected');
    }
  }

  /** @planks("I type {string} into the new-todo input and press Enter") */
  /** @planks("the app loads with active todo {string}") */
  function addTodo(title) {
    todos.push({ id: uid(), title: title, completed: false });
    save();
    render();
  }

  /** @planks("I complete the todo {string}") */
  function completeTodo(id) {
    var todo = todos.find(function (t) { return t.id === id; });
    if (!todo) return;
    todo.completed = !todo.completed;
    save();
    render();
  }

  /** @planks("I click the toggle-all control") */
  function toggleAllTodos() {
    var next = toggleAll.checked;
    todos.forEach(function (t) { t.completed = next; });
    save();
    render();
  }

  /** @planks("I set the edit input to {string} and press Enter") */
  function destroyTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    save();
    render();
  }

  /** @planks("I double-click the label of the todo {string}") */
  function enterEdit(li) {
    var editing = todoList.querySelectorAll('li.editing');
    for (var i = 0; i < editing.length; i++) editing[i].classList.remove('editing');
    li.classList.add('editing');
    var edit = li.querySelector('.edit');
    edit.focus();
  }

  /** @planks("I set the edit input to {string} and press Enter") */
  /** @planks("I set the edit input to {string} and blur") */
  function saveEdit(li) {
    if (!li.isConnected) return;
    var id = Number(li.dataset.id);
    var edit = li.querySelector('.edit');
    var value = edit.value.trim();
    if (value === '') {
      destroyTodo(id);
      return;
    }
    var todo = todos.find(function (t) { return t.id === id; });
    if (todo) todo.title = value;
    li.classList.remove('editing');
    save();
    render();
  }

  /** @planks("I set the edit input to {string} and press Escape") */
  function cancelEdit(li) {
    if (!li.isConnected) return;
    li.classList.remove('editing');
    render();
  }

  /** @planks("I click the clear-completed button") */
  function clearCompletedTodos() {
    todos = todos.filter(function (t) { return !t.completed; });
    save();
    render();
  }

  function init() {
    load();

    newTodoInput = document.querySelector('.new-todo');
    main = document.querySelector('#main');
    footer = document.querySelector('#footer');
    todoList = document.querySelector('.todo-list');
    toggleAll = document.querySelector('#toggle-all');
    clearCompleted = document.querySelector('.clear-completed');
    countEl = document.querySelector('.todo-count');

    newTodoInput.addEventListener('keydown', function (e) {
      if (e.key !== ENTER_KEY) return;
      var value = newTodoInput.value.trim();
      if (value !== '') addTodo(value);
      newTodoInput.value = '';
    });

    newTodoInput.focus();

    todoList.addEventListener('change', function (e) {
      var target = e.target;
      if (!target.classList.contains('toggle')) return;
      var li = target.closest('li');
      completeTodo(Number(li.dataset.id));
    });

    todoList.addEventListener('dblclick', function (e) {
      var label = e.target.closest('label');
      if (!label) return;
      enterEdit(label.closest('li'));
    });

    todoList.addEventListener('click', function (e) {
      var btn = e.target.closest('.destroy');
      if (!btn) return;
      var li = btn.closest('li');
      destroyTodo(Number(li.dataset.id));
    });

    todoList.addEventListener('keydown', function (e) {
      var target = e.target;
      if (!target.classList.contains('edit')) return;
      var li = target.closest('li');
      if (e.key === ENTER_KEY) saveEdit(li);
      else if (e.key === ESCAPE_KEY) cancelEdit(li);
    });

    todoList.addEventListener('blur', function (e) {
      var target = e.target;
      if (!target.classList.contains('edit') || !target.isConnected) return;
      saveEdit(target.closest('li'));
    }, true);

    toggleAll.addEventListener('change', toggleAllTodos);
    clearCompleted.addEventListener('click', clearCompletedTodos);

    window.addEventListener('hashchange', function () {
      setRoute();
      render();
    });

    render();
  }

  document.addEventListener('DOMContentLoaded', init);
})();

