cd /home/exedev/shipshape-shakedown/.eval-scratch/P6-cand-hy3/sim && node -e '
const fs=require("fs");
const app=fs.readFileSync("js/app.js","utf8");
const steps=fs.readFileSync("features/support/steps.js","utf8");
// extract @planks("...") and @planks-provisional("...")
const plankRe=/@planks(?:-provisional)?\("([^"]*)"\)/g;
const planks=[];let m;
while((m=plankRe.exec(app))) planks.push(m[1]);
// extract Given/When/Then("...") patterns (first string arg of each)
const stepRe=/(?:Given|When|Then)\(\s*"((?:[^"\\]|\\.)*)"/g;
const patterns=new Set();let s;
while((s=stepRe.exec(steps))) patterns.add(s[1]);
// also catch regex steps noted in planks? none expected.
console.log("plank count:",planks.length);
let bad=0;
for(const p of planks){
  if(patterns.has(p)){ /*ok*/ }
  else { console.log("UNJOINED PLANK:",p); bad++; }
}
console.log(bad===0?"PLANK JOIN CLEAN: all planks match a step-definition pattern":"PLANK JOIN FAIL: "+bad+" unjoined");
// report step patterns with no plank (informational; assertion/setup steps legitimately unplanked)
'

