const planks=[];let m;
while((m=plankRe.exec(app))) planks.push(m[1]);
// step defs use single quotes in this file
const stepRe=/(?:Given|When|Then)\(\s*\x27((?:[^\x27\\]|\\.)*)\x27/g;
const patterns=new Set();let s;
while((s=stepRe.exec(steps))) patterns.add(s[1]);
console.log("plank count:",planks.length,"| step patterns:",patterns.size);
let bad=0;
for(const p of planks){
  if(patterns.has(p)){ /*ok*/ }
  else { console.log("UNJOINED PLANK:",p); bad++; }
}
// provisional refs
const provRe=/@planks-provisional\("([^"]*)"\)/g;let pm;let prov=0;
while((pm=provRe.exec(app))){console.log("PROVISIONAL:",pm[1]);prov++;}
console.log(bad===0&&prov===0?"PLANK JOIN CLEAN: every @planks matches a current step pattern; no @planks-provisional":"ISSUES: unjoined="+bad+" provisional="+prov);
